INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3020, 5, 'Une voix qui ne vous lâche plus', 'Meursault raconte tout avec la même indifférence, l''enterrement comme la plage, et c''est justement ce ton plat qui finit par glacer. Relu vingt ans après le lycée, je l''ai trouvé beaucoup plus drôle et plus cruel que dans mon souvenir.', '2025-02-01 04:40:52', 'visible', '2025-02-02 11:29:07', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782070360024' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3059, 3, 'Relu pour le bac de mon fils', 'Court, efficace, mais je reste à distance du personnage. Je comprends pourquoi on l''étudie, moins pourquoi on l''aime.', '2025-08-26 15:35:33', 'visible', '2025-08-27 03:02:27', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782070360024' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3014, 4, 'La deuxième partie surtout', 'Le procès m''a davantage marquée que le meurtre lui-même : on juge un homme pour ne pas avoir pleuré sa mère. Ça reste d''une actualité étonnante.', '2025-08-01 17:07:54', 'visible', '2025-08-02 01:17:10', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782070360024' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3005, 4, 'Noir de chez noir', 'Zola enferme ses personnages dans une boutique humide du passage du Pont-Neuf et on étouffe avec eux. La culpabilité qui ronge Thérèse et Laurent est décrite presque comme une maladie physique.', '2024-09-12 18:39:27', 'visible', '2024-09-13 18:46:10', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782266082587' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3055, 2, 'Trop sombre pour moi', 'Je savais que ce n''était pas une comédie, mais trois cents pages de remords sans une respiration, c''était au-dessus de mes forces en ce moment.', '2024-07-01 13:56:42', 'visible', '2024-07-02 01:59:28', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782266082587' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3042, 5, 'À lire avec le documentaire', 'Les textes de Baldwin sur Medgar Evers, Malcolm X et Martin Luther King sont d''une précision terrible. J''ai enchaîné avec le film de Raoul Peck, les deux se complètent très bien.', '2025-12-29 22:02:38', 'visible', '2025-12-30 12:42:09', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782264073655' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3002, 4, 'Dense mais nécessaire', 'Ce n''est pas un livre qu''on lit d''une traite. Je l''ai pris par petites doses, en soulignant beaucoup.', '2025-06-10 15:36:35', 'visible', '2025-06-10 20:01:35', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782264073655' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3011, 5, 'Ophélie, mon héroïne préférée', 'Une héroïne maladroite, myope, qui traverse les miroirs et lit le passé des objets : j''ai adoré qu''elle ne soit pas une guerrière. L''univers des arches est foisonnant et Thorn est délicieusement désagréable.', '2025-02-22 16:09:21', 'visible', '2025-02-25 06:39:50', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782075215466' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3009, 4, 'Démarrage lent, fin addictive', 'Les cent premières pages m''ont paru longues avec toutes les intrigues de la Citacielle, puis je n''ai plus rien pu faire d''autre que lire. J''ai commandé le tome 2 dans la foulée.', '2026-08-19 16:31:25', 'visible', '2026-08-21 12:29:31', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782075215466' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3048, 3, 'Joli mais un peu long', 'Le style est soigné et l''imaginaire original. J''aurais aimé que l''histoire avance plus vite, surtout au Pôle.', '2025-06-24 07:48:01', 'visible', '2025-06-26 14:23:16', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782075215466' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3030, 5, 'Mon recueil de chevet', 'Je l''ouvre au hasard depuis des années. « L''Invitation au voyage » et « Harmonie du soir » me suivent partout, cette édition est agréable à tenir en main.', '2024-12-25 08:46:15', 'visible', '2024-12-27 12:25:18', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782253240570' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3042, 3, 'Beau, mais difficile seul', 'Sans les notes de mon ancien prof, certains poèmes m''auraient échappé. Les plus courts sont les plus forts pour moi.', '2026-07-16 20:09:51', 'visible', '2026-07-18 20:23:47', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782253240570' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3028, 4, 'Le big bang expliqué à ma grand-mère', 'Hawking arrive à parler de trous noirs et de temps imaginaire sans une seule équation, ou presque. J''ai décroché sur deux chapitres, mais le reste est limpide.', '2025-09-10 20:06:33', 'visible', '2025-09-12 10:57:04', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782080297136' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3047, 5, 'Le livre qui m’a fait choisir la physique', 'Lu à seize ans, relu à trente. Le passage sur la flèche du temps m''impressionne toujours autant.', '2024-12-13 01:58:47', 'visible', '2024-12-15 02:52:06', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782080297136' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3057, 4, 'Drôle et instructif', 'Qui aurait cru qu''un livre sur la digestion pouvait être aussi amusant ? Giulia Enders a un vrai sens de la pédagogie, les petits dessins aident beaucoup.', '2024-05-01 18:06:20', 'visible', '2024-05-03 16:55:55', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782330188481' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3006, 3, 'Bonne vulgarisation', 'Intéressant sur le microbiote, mais quelques chapitres m''ont paru datés depuis sa sortie. À compléter avec des sources plus récentes.', '2025-06-25 21:58:08', 'visible', '2025-06-26 05:33:17', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782330188481' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3016, 5, 'La bible de la cuisine familiale', 'On y trouve tout, du pot-au-feu à la pâte à choux. Pas de photos, mais des recettes qui marchent à tous les coups. Mon exemplaire d''occasion avait même une recette annotée au crayon par son ancien propriétaire, j''ai adoré.', '2025-12-30 15:22:48', 'visible', '2025-12-30 19:40:02', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782226441133' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3023, 4, 'Indispensable pour débuter', 'J''ai quitté le foyer familial avec ce livre et je ne le regrette pas. Les quantités sont parfois à adapter, c''est une cuisine d''une autre époque.', '2026-09-17 04:51:04', 'visible', '2026-09-18 06:07:16', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782226441133' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3027, 5, 'Le Goncourt le plus ludique', 'Un avion qui atterrit deux fois à trois mois d''intervalle, et des passagers qui se retrouvent face à leur double : le point de départ est génial et Le Tellier s''amuse avec tous les genres. Les dernières pages m''ont laissé un sourire en coin.', '2026-02-20 11:56:49', 'visible', '2026-02-22 18:25:54', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782072965821' ORDER BY l.id_livre LIMIT 1;
INSERT IGNORE INTO avis (id_livre, id_user, note, titre, commentaire, date_creation, statut, date_validation, id_validateur) SELECT l.id_livre, 3046, 3, 'Brillant mais froid', 'Très habile, presque trop. J''ai admiré la construction sans m''attacher vraiment à un seul personnage.', '2025-12-05 06:22:40', 'visible', '2025-12-07 17:15:55', (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1) FROM livre l WHERE l.isbn = '9782072965821' ORDER BY l.id_livre LIMIT 1;
