INSERT IGNORE INTO evenement (id_evenement, titre, description, type, auteurs, lieu, date_debut, date_fin, places_max, attente_auto, statut, image, id_createur, date_creation) VALUES
(2001, 'Club manga : premiers tomes à partager', 'Chacun apporte le premier tome d''une série qu''il aime et le présente en trois minutes. Échanges de mangas possibles en fin de séance. Entrée libre, sur inscription.', 'rencontre', NULL, 'Café-librairie partenaire, Paris 11e', '2026-11-14 15:00:00', '2026-11-14 17:00:00', 25, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-23 14:36:44'),
(2002, 'Atelier : réparer et couvrir ses livres', 'Recoller une reliure, couvrir un livre de poche, effacer des traces de crayon : un atelier pratique pour prolonger la vie de vos livres. Matériel fourni. Participation gratuite.', 'atelier', NULL, 'Médiathèque du quartier, Paris 13e', '2026-11-18 18:30:00', '2026-11-18 20:00:00', 12, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-07 14:36:44'),
(2003, 'Troc de livres de novembre', 'Apportez jusqu''à cinq livres en bon état et repartez avec autant d''autres. Les livres restants sont proposés en don sur le site. Gratuit.', 'atelier', NULL, 'Halle associative, Montreuil', '2026-11-21 10:00:00', '2026-11-21 14:00:00', 60, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-14 14:36:44'),
(2004, 'Lecture-dédicace : « Les Ombres de la Croix-Rousse »', 'Élise Marchand lit des extraits de son polar et dédicace les exemplaires apportés ou achetés sur place. Gratuit.', 'dedicace', 'Élise Marchand', 'Librairie partenaire, Paris 6e', '2026-11-25 18:30:00', '2026-11-25 20:00:00', 30, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-26 14:36:44'),
(2005, 'Quiz littéraire : spécial science-fiction', 'Équipes de deux à cinq joueurs, cinq manches de questions sur la SF en livres, BD et films. Petits lots pour les gagnants. Participation gratuite pour tous.', 'rencontre', NULL, 'Bar associatif partenaire, Paris 19e', '2026-11-27 20:00:00', '2026-11-27 22:30:00', 40, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-29 14:36:44'),
(2006, 'Heure du conte : albums d’hiver', 'Lectures d''albums pour les 3-6 ans, suivies d''un petit coloriage. Les parents restent avec les enfants. Gratuit.', 'atelier', NULL, 'Bibliothèque jeunesse partenaire, Vincennes', '2026-12-02 10:30:00', '2026-12-02 11:30:00', 15, 0, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-22 14:36:44'),
(2007, 'Conférence : comment naît une traduction de manga', 'Une traductrice professionnelle raconte son métier : délais, onomatopées, jeux de mots intraduisibles et relations avec les éditeurs japonais. Entrée gratuite pour tous.', 'rencontre', NULL, 'Auditorium de la maison des associations, Paris 14e', '2026-12-05 16:00:00', '2026-12-05 17:45:00', 80, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-20 14:36:44'),
(2008, 'Dédicace BD jeunesse', 'Rencontre avec un auteur-illustrateur de bande dessinée jeunesse, dessins dédicacés pour les enfants. Gratuit, un livre par enfant.', 'dedicace', 'Bastien Lemoine', 'Librairie jeunesse partenaire, Boulogne-Billancourt', '2026-12-09 14:00:00', '2026-12-09 17:00:00', 35, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-16 14:36:44'),
(2009, 'Club de lecture : « Veiller sur elle »', 'Discussion autour du roman de Jean-Baptiste Andrea. Lecture préalable conseillée, ambiance détendue. Gratuit.', 'rencontre', NULL, 'Salon de thé partenaire, Paris 9e', '2026-12-12 17:00:00', '2026-12-12 19:00:00', 14, 0, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-16 14:36:44'),
(2010, 'Atelier d’écriture : nouvelle de Noël', 'Deux heures pour écrire une courte nouvelle à partir d''objets tirés au sort. Débutants bienvenus. Participation gratuite.', 'atelier', NULL, 'Tiers-lieu culturel, Saint-Denis', '2026-12-16 19:00:00', '2026-12-16 21:00:00', 10, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-29 14:36:44'),
(2011, 'Grand troc de Noël', 'Échange de livres, de BD et de mangas avant les fêtes, coin emballage cadeau avec papier recyclé. Gratuit.', 'atelier', NULL, 'Parvis de la mairie, Lyon 3e', '2026-12-19 10:00:00', '2026-12-19 15:00:00', 80, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-16 14:36:44'),
(2012, 'Rencontre : polar nordique', 'Une libraire spécialisée présente dix romans noirs scandinaves incontournables et échange avec le public. Gratuit.', 'rencontre', NULL, 'Bibliothèque municipale partenaire, Lille', '2027-01-09 15:00:00', '2027-01-09 16:30:00', 40, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-25 14:36:44'),
(2013, 'Club manga : les séries terminées', 'Séance consacrée aux séries complètes à conseiller à ceux qui n''aiment pas attendre les sorties. Gratuit.', 'rencontre', NULL, 'Café-librairie partenaire, Paris 11e', '2027-01-16 15:00:00', '2027-01-16 17:00:00', 25, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-10 14:36:44'),
(2014, 'Atelier : initiation au fanzine', 'Découper, coller, dessiner : on fabrique ensemble un petit fanzine photocopié autour d''un livre aimé. Matériel fourni. Participation gratuite.', 'atelier', NULL, 'Atelier associatif, Paris 20e', '2027-01-23 14:00:00', '2027-01-23 17:00:00', 12, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-16 14:36:44'),
(2015, 'Lecture musicale : poèmes de Prévert', 'Une comédienne et un guitariste revisitent « Paroles ». Entrée gratuite pour tous.', 'rencontre', NULL, 'Petite salle de spectacle partenaire, Paris 18e', '2027-01-29 20:30:00', '2027-01-29 21:45:00', 50, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-01 14:36:44'),
(2016, 'Quiz famille : contes et héros de notre enfance', 'Un quiz pour jouer en famille, dès 7 ans, sur les contes, les albums et les héros de romans jeunesse. Gratuit.', 'rencontre', NULL, 'Médiathèque partenaire, Versailles', '2027-02-06 15:00:00', '2027-02-06 16:30:00', 30, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-23 14:36:44'),
(2017, 'Rencontre : écrire pour les ados', 'Table ronde avec deux autrices de romans young adult sur leurs personnages, leurs lecteurs et les réseaux sociaux. Gratuit.', 'rencontre', NULL, 'Auditorium partenaire, Nantes', '2027-02-13 16:00:00', '2027-02-13 17:45:00', 120, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-01 14:36:44'),
(2018, 'Atelier : tenir un carnet de lecture', 'Méthodes et astuces pour garder la trace de ses lectures : citations, collages, notes. Gratuit, carnet fourni.', 'atelier', NULL, 'Papeterie-atelier partenaire, Bordeaux', '2027-02-20 10:30:00', '2027-02-20 12:30:00', 12, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-20 14:36:44'),
(2019, 'Troc spécial manuels et livres scolaires', 'Échange de manuels, d''annales et de classiques au programme, du collège à la licence. Gratuit.', 'atelier', NULL, 'Maison des étudiants partenaire, Paris 5e', '2027-03-06 13:00:00', '2027-03-06 17:00:00', 70, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-08 14:36:44'),
(2020, 'Conférence : le roman graphique, un genre adulte', 'Histoire du roman graphique de « Maus » à « Persepolis » et à la production actuelle, avec projections. Entrée gratuite.', 'rencontre', NULL, 'Salle de conférence partenaire, Toulouse', '2027-03-13 18:00:00', '2027-03-13 19:30:00', 60, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-22 14:36:44'),
(2021, 'Dédicace : polars lyonnais', 'Séance de dédicace et échanges sur l''écriture d''un polar ancré dans un quartier. Gratuit.', 'dedicace', 'Élise Marchand', 'Librairie partenaire, Lyon 4e', '2027-03-20 15:00:00', '2027-03-20 17:00:00', 30, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-09 14:36:44'),
(2022, 'Quiz manga et anime', 'Blind test des génériques et questions sur les grandes séries, en équipes. Participation gratuite.', 'rencontre', NULL, 'Bar associatif partenaire, Paris 19e', '2027-04-02 20:00:00', '2027-04-02 22:30:00', 40, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-06 14:36:44'),
(2023, 'Lecture partagée au jardin', 'Lecture à voix haute de textes courts sur la nature, chacun peut apporter le sien. Prévoir un plaid. Gratuit.', 'atelier', NULL, 'Jardin partagé partenaire, Paris 20e', '2027-05-15 15:00:00', '2027-05-15 17:00:00', 25, 1, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-09-30 14:36:44'),
(2024, 'Petit club : coin des 8-11 ans', 'Les jeunes lecteurs présentent leur livre préféré et repartent avec une liste d''idées de lecture. Gratuit.', 'rencontre', NULL, 'Bibliothèque jeunesse partenaire, Créteil', '2026-11-28 14:30:00', '2026-11-28 15:45:00', 8, 0, 'publie', NULL, (SELECT u.id FROM `user` u WHERE u.role = 'admin' ORDER BY u.id LIMIT 1), '2026-10-21 14:36:44');
